<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/auth.php';
$user=current_user();if(!$user){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['expense_id']??null,FILTER_VALIDATE_INT);$operation=(string)($_POST['operation']??'');if(!$id||!in_array($operation,['review','pay'],true)){$_SESSION['error']='Select a valid expense action.';header('Location: ../?page=expenses');exit;}
$pdo=db();try{$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT * FROM school_expenses WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$expense=$stmt->fetch();if(!$expense)throw new DomainException('Expense not found.');
if($operation==='review'){$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['review_note']??''));if(!in_array($user['role'],['Administrator','Head'],true))throw new DomainException('Only the school administrator or head can review expenses.');if((int)$expense['created_by']===(int)$user['id'])throw new DomainException('The submitter cannot review their own expense.');if($expense['status']!=='Submitted')throw new DomainException('Only submitted expenses can be reviewed.');if(!in_array($decision,['Approved','Rejected'],true)||strlen($note)>500||($decision==='Rejected'&&$note===''))throw new DomainException('A rejection needs a short review note.');$update=$pdo->prepare('UPDATE school_expenses SET status=:status,reviewed_by=:user,reviewed_at=NOW(),review_note=:note WHERE id=:id AND status=\'Submitted\'');$update->execute(['status'=>$decision,'user'=>$user['id'],'note'=>$note?:null,'id'=>$id]);if($update->rowCount()!==1)throw new DomainException('Expense state changed. Reload the register.');audit_log('expenses.reviewed','school_expenses',$id,['decision'=>$decision]);$_SESSION['notice']=$decision==='Approved'?'Expense approved for payment.':'Expense rejected with review note.';}
else{$method=(string)($_POST['payment_method']??'');$reference=trim((string)($_POST['payment_reference']??''));if(!in_array($user['role'],['Administrator','Bursar'],true))throw new DomainException('Only the administrator or bursar can record expense payments.');if($expense['status']!=='Approved')throw new DomainException('Only approved expenses can be marked paid.');if((int)$expense['reviewed_by']===(int)$user['id'])throw new DomainException('The expense approver cannot record payment for the same expense.');if(!in_array($method,['Cash','EcoCash','Bank transfer','Swipe','Other'],true)||strlen($reference)>100)throw new DomainException('Check the payment details.');$update=$pdo->prepare('UPDATE school_expenses SET status=\'Paid\',paid_by=:user,paid_at=NOW(),payment_method=:method,payment_reference=:reference WHERE id=:id AND status=\'Approved\'');$update->execute(['user'=>$user['id'],'method'=>$method,'reference'=>$reference?:null,'id'=>$id]);if($update->rowCount()!==1)throw new DomainException('Expense state changed. Reload the register.');audit_log('expenses.paid','school_expenses',$id,['currency'=>$expense['currency'],'amount'=>$expense['amount'],'method'=>$method]);$_SESSION['notice']='Expense payment recorded.';}
$pdo->commit();}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Expense transition failed: '.$e->getMessage());$_SESSION['error']='Could not update this expense.';}
header('Location: ../?page=expenses');exit;
